#include <stdint.h>
#include <stdint.h>

/* RCC Addresses */
#define RCC_BASE_ADDR           0x40023800UL

#define RCC_APB2ENR_OFFSET      0x44UL

#define RCC_APB2ENR_ADDR        (RCC_BASE_ADDR + RCC_APB2ENR_OFFSET)

#define RCC_ADC1_ENABLE_BIT     8UL

/* ADC Addresses*/
#define ADC_BASE_ADDR           0x40012000UL

#define ADC_CR1_REG_OFFSET      0x04UL

#define ADC_CR1_REG_ADDR        (ADC_BASE_ADDR + ADC_CR1_REG_OFFSET)

#define ADC_CR1_SCAN_MODE_BIT   8UL

int main(void)
{
  uint32_t *pAdcCr1Reg = (uint32_t *)ADC_CR1_REG_ADDR;
  uint32_t *pRccApb2Enr = (uint32_t *)RCC_APB2ENR_ADDR;

  /* 1. Enable the peripheral clock for ADC1 */
  *pRccApb2Enr |= (1 << RCC_ADC1_ENABLE_BIT);

  /* 2. Modify the ADC CR1 register */
  *pAdcCr1Reg |= (1 << ADC_CR1_SCAN_MODE_BIT);

  for(;;);

}
